```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

struct Node;

/// Truncate `s` to at most `max` bytes without splitting a UTF-8 char.
fn truncate_bytes(mut s: String, max: usize) -> String {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s.truncate(end);
    s
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let cq = query.query;

        // ensures len(question) <= 512.
        // The requires already bounds the input at 512; this truncation makes the
        // postcondition hold unconditionally, defensively, at a char boundary.
        let question = truncate_bytes(cq.question, 512);

        // The one import this node is granted: read-only lookup in 'knowledge-base'.
        let mut knowledge = kb_read::lookup(&question);

        // ensures present(knowledge): never hand back an empty knowledge list.
        if knowledge.is_empty() {
            knowledge.push(String::from(
                "No knowledge-base entries matched this query.",
            ));
        }

        ConversationContext {
            intent: cq.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

